insert into REP_PROD_INFO( PROD_ID, PROD_RE, PROD_NAME, PROD_ABBR, RAISE_MIN, RAISE_MAX, RAISE_STRDATE, RAISE_ENDDATE, RAISE_CCY, SET_DATE, VDATE, FIRST_OPEN_DAY, MDATE, ACT_MDATE, TERM, WINDUP_DATE, ISSUE_MODE, PROFIT_TYPE, PROD_TYPE, RAISE_TYPE, RISK_LEVEL, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, RAISE_AMT, OPEN_MODE, INVEST_PROF_DATE, INVEST_PRIN_DATE, IS_INDEPE_ACC, PROD_INVEST_TYPE, REVEAL_CHANNEL, DEAL_CAL, STATUS, FINA_TYPE, TRU_ACCOUNT, ACCT_CHNNAME, TRU_FEE_RAGE, TRU_ACCOUNT_NUM, TRU_ACCOUNT_NAME, PROD_TERM_TYPE, BASIS, IS_LAYER, PRO_MANAGER, PRO_CUSTODIAN, HUGE_REDEEM_THRESHOLD, SALE_AMT_STR, OPERATE_MODE, F_PROD_ID) select PROD_ID, PROD_RE, PROD_NAME, PROD_ABBR, RAISE_MIN, RAISE_MAX, RAISE_STRDATE, RAISE_ENDDATE, RAISE_CCY, SET_DATE, VDATE, FIRST_OPEN_DAY, MDATE, ACT_MDATE, TERM, WINDUP_DATE, ISSUE_MODE, PROFIT_TYPE, PROD_TYPE, RAISE_TYPE, RISK_LEVEL, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, RAISE_AMT, OPEN_MODE, INVEST_PROF_DATE, INVEST_PRIN_DATE, IS_INDEPE_ACC, PROD_INVEST_TYPE, REVEAL_CHANNEL, DEAL_CAL, STATUS, FINA_TYPE, TRU_ACCOUNT, ACCT_CHNNAME, TRU_FEE_RAGE, TRU_ACCOUNT_NUM, TRU_ACCOUNT_NAME, PROD_TERM_TYPE, BASIS, IS_LAYER, PRO_MANAGER, PRO_CUSTODIAN, HUGE_REDEEM_THRESHOLD, SALE_AMT_STR, OPERATE_MODE, F_PROD_ID from ( select TEMP.* from (
SELECT #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.prodRe,jdbcType=VARCHAR} PROD_RE, #{item.prodName,jdbcType=VARCHAR} PROD_NAME, #{item.prodAbbr,jdbcType=VARCHAR} PROD_ABBR, #{item.raiseMin,jdbcType=VARCHAR} RAISE_MIN, #{item.raiseMax,jdbcType=VARCHAR} RAISE_MAX, #{item.raiseStrdate,jdbcType=DATE} RAISE_STRDATE, #{item.raiseEnddate,jdbcType=DATE} RAISE_ENDDATE, #{item.raiseCcy,jdbcType=VARCHAR} RAISE_CCY, #{item.setDate,jdbcType=DATE} SET_DATE, #{item.vdate,jdbcType=DATE} VDATE, #{item.firstOpenDay,jdbcType=DATE} FIRST_OPEN_DAY, #{item.mdate,jdbcType=DATE} MDATE, #{item.actMdate,jdbcType=DATE} ACT_MDATE, #{item.term,jdbcType=VARCHAR} TERM, #{item.windupDate,jdbcType=DATE} WINDUP_DATE, #{item.issueMode,jdbcType=VARCHAR} ISSUE_MODE, #{item.profitType,jdbcType=VARCHAR} PROFIT_TYPE, #{item.prodType,jdbcType=VARCHAR} PROD_TYPE, #{item.raiseType,jdbcType=VARCHAR} RAISE_TYPE, #{item.riskLevel,jdbcType=VARCHAR} RISK_LEVEL, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.raiseAmt,jdbcType=DECIMAL} RAISE_AMT, #{item.openMode,jdbcType=VARCHAR} OPEN_MODE, #{item.investProfDate,jdbcType=VARCHAR} INVEST_PROF_DATE, #{item.investPrinDate,jdbcType=VARCHAR} INVEST_PRIN_DATE, #{item.isIndepeAcc,jdbcType=VARCHAR} IS_INDEPE_ACC, #{item.prodInvestType,jdbcType=VARCHAR} PROD_INVEST_TYPE, #{item.revealChannel,jdbcType=VARCHAR} REVEAL_CHANNEL, #{item.dealCal,jdbcType=VARCHAR} DEAL_CAL, #{item.status,jdbcType=VARCHAR} STATUS, #{item.finaType,jdbcType=VARCHAR} FINA_TYPE, #{item.truAccount,jdbcType=VARCHAR} TRU_ACCOUNT, #{item.acctChnname,jdbcType=VARCHAR} ACCT_CHNNAME, #{item.truFeeRage,jdbcType=DECIMAL} TRU_FEE_RAGE, #{item.truAccountNum,jdbcType=VARCHAR} TRU_ACCOUNT_NUM, #{item.truAccountName,jdbcType=VARCHAR} TRU_ACCOUNT_NAME, #{item.prodTermType,jdbcType=VARCHAR} PROD_TERM_TYPE, #{item.basis,jdbcType=VARCHAR} BASIS, #{item.isLayer,jdbcType=VARCHAR} IS_LAYER, #{item.proManager,jdbcType=VARCHAR} PRO_MANAGER, #{item.proCustodian,jdbcType=VARCHAR} PRO_CUSTODIAN, #{item.hugeRedeemThreshold,jdbcType=DECIMAL} HUGE_REDEEM_THRESHOLD, #{item.saleAmtStr,jdbcType=DECIMAL} SALE_AMT_STR, #{item.operateMode,jdbcType=VARCHAR} OPERATE_MODE, #{item.fProdId,jdbcType=VARCHAR} F_PROD_ID FROM dual
) TEMP where not exists (select 1 from REP_PROD_INFO CII where CII.PROD_ID = TEMP.PROD_ID) ) de ;
